#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
#
# My Builder App account setup (ticket #25 of spec #23).
#
# Walks a human through creating every service account the platform needs,
# all owned by Grassroots Headquarters, and stores each key where the delivery
# pipeline reads it: GitHub Actions secrets/variables, Vercel environment
# settings and Supabase Edge Function secrets. Captured values are also kept
# in a git-ignored .env.accounts at the repo root so the wizard can be re-run
# (Enter keeps a saved value). Nothing secret is ever printed.
#
# Run from anywhere:  bash scripts/setup-accounts.sh
# Needs: gh (logged in), node/npx, curl. jq is optional (enables automation).

REPO_ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)

# Sentry project names and the mobile app id are fixed by the contracts.
SENTRY_PROJECT_ADMIN="my-builder-admin"
SENTRY_PROJECT_MOBILE="my-builder-mobile"
SENTRY_PROJECT_EDGE="my-builder-edge-functions"
APP_ID="com.grassrootshq.mybuilderapp"

die() { warn "$1"; exit 1; }

require_cmd() {
  command -v "$1" >/dev/null 2>&1 || die "$1 is required: $2"
}

# supabase_cli ... runs the Supabase CLI without a global install.
supabase_cli() { npx -y supabase@latest "$@"; }

# looks_like_ref VALUE warns when VALUE is not a 20-letter Supabase project ref.
looks_like_ref() {
  [[ "$1" =~ ^[a-z]{20}$ ]] || warn "'$1' does not look like a Supabase project ref (20 lowercase letters); carry on if you are sure"
}

# supabase_url REF is the API URL of a hosted project.
supabase_url() { printf 'https://%s.supabase.co' "$1"; }

# configure_phone_auth REF enables Phone login with Twilio Verify through the
# Supabase Management API. Returns non-zero (quietly) if the API refuses, so
# the caller can fall back to the dashboard.
configure_phone_auth() {
  local ref="$1" body
  command -v jq >/dev/null 2>&1 || return 1
  body=$(jq -n \
    --arg sid "$TWILIO_ACCOUNT_SID" --arg token "$TWILIO_AUTH_TOKEN" --arg verify "$TWILIO_VERIFY_SERVICE_SID" \
    '{external_phone_enabled: true, sms_provider: "twilio_verify", sms_autoconfirm: false,
      sms_twilio_verify_account_sid: $sid, sms_twilio_verify_auth_token: $token,
      sms_twilio_verify_message_service_sid: $verify}')
  printf '%s' "$body" | curl -fsS -o /dev/null -X PATCH \
    -H "Authorization: Bearer $SUPABASE_ACCESS_TOKEN" -H "Content-Type: application/json" \
    --data @- "https://api.supabase.com/v1/projects/$ref/config/auth" 2>/dev/null
}

# edge_secrets REF NAME=VALUE... sets Edge Function secrets on a hosted project
# through a 0600 temp file so no value appears on a command line or screen.
edge_secrets() {
  local ref="$1" tmp; shift
  tmp=$(mktemp)
  chmod 600 "$tmp"
  printf '%s\n' "$@" > "$tmp"
  local kv names=""
  for kv in "$@"; do names+="${kv%%=*} "; done
  if SUPABASE_ACCESS_TOKEN="$SUPABASE_ACCESS_TOKEN" supabase_cli secrets set --project-ref "$ref" --env-file "$tmp" >/dev/null 2>&1; then
    printf '  %s✓ set%s %s Edge Function secret(s) on %s\n' "$GREEN" "$RESET" "$#" "$ref"
  else
    SKIPPED+=("Edge Function secrets on $ref: pnpm supabase secrets set --project-ref $ref --env-file <file with ${names% }>")
    warn "couldn't set Edge Function secrets on $ref; listed under 'still to do' at the end"
  fi
  rm -f "$tmp"
}

# vercel_env DIR NAME VALUE ENVIRONMENT writes one Vercel environment variable
# for the project linked in DIR, overwriting any existing one.
vercel_env() {
  local dir="$1" name="$2" value="$3" environment="$4"
  if (cd "$dir" && printf '%s' "$value" | npx -y vercel@latest env add "$name" "$environment" --force >/dev/null 2>&1); then
    printf '  %s✓ set%s Vercel %s (%s)\n' "$GREEN" "$RESET" "$name" "$environment"
  else
    SKIPPED+=("Vercel env var $name ($environment) on $(basename "$dir") project")
    warn "couldn't set Vercel $name ($environment); add it in the dashboard"
  fi
}

# vercel_link DIR PROJECT links DIR to an existing Vercel project (logging in first if needed).
vercel_link() {
  local dir="$1" project="$2"
  if ! npx -y vercel@latest whoami >/dev/null 2>&1; then
    step "The Vercel CLI needs to log in: follow its prompts (pick the Grassroots Headquarters team)."
    npx -y vercel@latest login || return 1
  fi
  (cd "$dir" && npx -y vercel@latest link --yes --scope "$VERCEL_TEAM" --project "$project" >/dev/null 2>&1)
}

run_wizard() {

TOTAL_STAGES=14
ENV_FILE="${ACCOUNTS_ENV_FILE:-$REPO_ROOT/.env.accounts}"

require_cmd gh "install from https://cli.github.com and run 'gh auth login'"
require_cmd npx "install Node 24 (source ~/.nvm/nvm.sh && nvm use 24)"
require_cmd curl "install curl"
cd "$REPO_ROOT"

banner "My Builder App: service accounts"

# ── 1. GitHub ─────────────────────────────────────────────────────────────
stage "GitHub: access, repository and environments"
say "CI secrets are written with gh, so it must be logged in as someone who can administer the repository."
if ! gh auth status >/dev/null 2>&1; then
  warn "gh is not logged in."
  step "In another terminal run: gh auth login   (GitHub.com, HTTPS, log in with a browser)"
  pause "Press Enter once gh auth login has finished"
  gh auth status >/dev/null 2>&1 || die "gh is still not logged in; re-run this wizard afterwards."
fi
GITHUB_REPO=$(gh api repos/{owner}/{repo} --jq .full_name 2>/dev/null) \
  || die "couldn't work out the GitHub repository from this checkout's remote"
say "Repository: $GITHUB_REPO"
step "Check the repository belongs to the Grassroots Headquarters organisation (not a personal account); transfer it first if not."
pause
say "Creating the GitHub environments the release pipeline deploys through."
if gh api -X PUT "repos/$GITHUB_REPO/environments/staging" >/dev/null 2>&1; then
  say "${GREEN}✓${RESET} environment 'staging' (no approval needed)"
else
  warn "couldn't create environment 'staging'"
  SKIPPED+=("GitHub environment 'staging': https://github.com/$GITHUB_REPO/settings/environments")
fi
GH_USER_ID=$(gh api user --jq .id 2>/dev/null || true)
GH_LOGIN=$(gh api user --jq .login 2>/dev/null || true)
if [[ -n "$GH_USER_ID" ]] && printf '{"reviewers":[{"type":"User","id":%s}]}' "$GH_USER_ID" \
     | gh api -X PUT "repos/$GITHUB_REPO/environments/production" --input - >/dev/null 2>&1; then
  say "${GREEN}✓${RESET} environment 'production' with @$GH_LOGIN as required reviewer (add the rest of the team there)"
else
  warn "couldn't set required reviewers on 'production' (a private repository needs GitHub Pro or Team for this)."
  SKIPPED+=("GitHub environment 'production' with required reviewers: https://github.com/$GITHUB_REPO/settings/environments")
fi
open_url "https://github.com/$GITHUB_REPO/settings/environments"
step "Confirm both environments are listed and 'production' shows Required reviewers. Add other reviewers now if you like."
pause

# ── 2. Supabase organisation + token ──────────────────────────────────────
stage "Supabase: organisation and access token"
open_url "https://supabase.com/dashboard/organizations"
step "Sign in with a Grassroots Headquarters login (not a personal one)."
step "If there is no organisation called 'Grassroots Headquarters', click New organization, name it that, and choose the Pro plan."
note "Production must be on Pro (daily backups, never pauses). Staging lives in the same organisation; it adds a small compute charge."
pause "Press Enter when the organisation exists"
open_url "https://supabase.com/dashboard/account/tokens"
step "Generate new token → name 'my-builder-app ci' → copy it (it is shown once)."
ask_secret SUPABASE_ACCESS_TOKEN "Paste the Supabase access token:"
write_env SUPABASE_ACCESS_TOKEN "$SUPABASE_ACCESS_TOKEN"
if SUPABASE_ACCESS_TOKEN="$SUPABASE_ACCESS_TOKEN" supabase_cli projects list >/dev/null 2>&1; then
  say "${GREEN}✓${RESET} the token works with the Supabase CLI"
else
  warn "the Supabase CLI couldn't list projects with that token; check it if later stages fail"
fi

# ── 3. Supabase staging ───────────────────────────────────────────────────
stage "Supabase: staging project"
open_url "https://supabase.com/dashboard/new"
step "Organisation: Grassroots Headquarters. Name: my-builder-app-staging. Region: West EU (London)."
step "Click Generate a password for the database and copy it now; the dashboard never shows it again."
ask_secret SUPABASE_STAGING_DB_PASSWORD "Paste the staging database password:"
write_env SUPABASE_STAGING_DB_PASSWORD "$SUPABASE_STAGING_DB_PASSWORD"
step "Create new project and wait for it to finish setting up."
step "The project ref is the 20-letter id in the address bar: https://supabase.com/dashboard/project/<ref>"
ask SUPABASE_STAGING_PROJECT_REF "Paste the staging project ref:"
looks_like_ref "$SUPABASE_STAGING_PROJECT_REF"
write_env SUPABASE_STAGING_PROJECT_REF "$SUPABASE_STAGING_PROJECT_REF"
write_env SUPABASE_STAGING_URL "$(supabase_url "$SUPABASE_STAGING_PROJECT_REF")"
open_url "https://supabase.com/dashboard/project/$SUPABASE_STAGING_PROJECT_REF/settings/api-keys"
step "Copy the anon public key (Legacy API keys tab → anon). Never the service_role or a secret key."
ask SUPABASE_STAGING_ANON_KEY "Paste the staging anon key:"
write_env SUPABASE_STAGING_ANON_KEY "$SUPABASE_STAGING_ANON_KEY"

# ── 4. Supabase production ────────────────────────────────────────────────
stage "Supabase: production project (Pro, daily backups)"
open_url "https://supabase.com/dashboard/new"
step "Organisation: Grassroots Headquarters. Name: my-builder-app-production. Region: West EU (London)."
step "Generate a database password and copy it now."
ask_secret SUPABASE_PRODUCTION_DB_PASSWORD "Paste the production database password:"
write_env SUPABASE_PRODUCTION_DB_PASSWORD "$SUPABASE_PRODUCTION_DB_PASSWORD"
step "Create new project and wait for it to finish setting up."
ask SUPABASE_PRODUCTION_PROJECT_REF "Paste the production project ref:"
looks_like_ref "$SUPABASE_PRODUCTION_PROJECT_REF"
write_env SUPABASE_PRODUCTION_PROJECT_REF "$SUPABASE_PRODUCTION_PROJECT_REF"
write_env SUPABASE_PRODUCTION_URL "$(supabase_url "$SUPABASE_PRODUCTION_PROJECT_REF")"
open_url "https://supabase.com/dashboard/project/$SUPABASE_PRODUCTION_PROJECT_REF/settings/api-keys"
step "Copy the anon public key (Legacy API keys tab → anon)."
ask SUPABASE_PRODUCTION_ANON_KEY "Paste the production anon key:"
write_env SUPABASE_PRODUCTION_ANON_KEY "$SUPABASE_PRODUCTION_ANON_KEY"
open_url "https://supabase.com/dashboard/project/$SUPABASE_PRODUCTION_PROJECT_REF/database/backups/scheduled"
step "Confirm daily backups are shown as enabled. If the page says backups need a paid plan, the organisation is not on Pro: upgrade it and come back."
note "Optional on Pro: Point in Time Recovery for finer restores; it costs extra."
confirm "Are daily backups enabled on production?" || SKIPPED+=("Supabase production daily backups (organisation must be on Pro)")

# ── 5. Twilio ─────────────────────────────────────────────────────────────
stage "Twilio: account and Verify service"
open_url "https://console.twilio.com"
step "Sign in to the Grassroots Headquarters Twilio account (create one at twilio.com/try-twilio if needed, as a business)."
step "Upgrade it from trial (Billing → add a payment method): trial accounts can only text verified numbers."
step "On the console home, Account Info shows the Account SID (AC…) and Auth Token."
ask TWILIO_ACCOUNT_SID "Paste the Account SID:"
write_env TWILIO_ACCOUNT_SID "$TWILIO_ACCOUNT_SID"
ask_secret TWILIO_AUTH_TOKEN "Paste the Auth Token:"
write_env TWILIO_AUTH_TOKEN "$TWILIO_AUTH_TOKEN"
open_url "https://console.twilio.com/us1/develop/verify/services"
step "Create new → Friendly name 'My Builder App' (it appears in the SMS: 'Your My Builder App verification code is…') → Create."
step "Copy the Service SID (VA…) from the service's settings page."
ask TWILIO_VERIFY_SERVICE_SID "Paste the Verify Service SID:"
write_env TWILIO_VERIFY_SERVICE_SID "$TWILIO_VERIFY_SERVICE_SID"
open_url "https://console.twilio.com/us1/develop/sms/services"
step "Create Messaging Service → name 'My Builder App Invites', use case 'Notify my users'."
step "Add a sender: buy a UK mobile number (needs a UK regulatory bundle and address), or add an alphanumeric sender id such as MYBUILDER."
step "Copy the Messaging Service SID (MG…). Edge Functions send Invite SMS through it."
ask TWILIO_MESSAGING_SERVICE_SID "Paste the Messaging Service SID:"
write_env TWILIO_MESSAGING_SERVICE_SID "$TWILIO_MESSAGING_SERVICE_SID"

# ── 6. Supabase phone login ───────────────────────────────────────────────
stage "Supabase: phone login with Twilio Verify (both projects)"
for env_name in staging production; do
  if [[ "$env_name" == staging ]]; then ref="$SUPABASE_STAGING_PROJECT_REF"; else ref="$SUPABASE_PRODUCTION_PROJECT_REF"; fi
  say "${BOLD}$env_name${RESET} ($ref)"
  if configure_phone_auth "$ref"; then
    say "${GREEN}✓${RESET} Phone provider set to Twilio Verify through the Management API"
  else
    warn "couldn't configure it through the Management API; set it in the dashboard:"
  fi
  open_url "https://supabase.com/dashboard/project/$ref/auth/providers"
  step "Expand Phone: Enable Phone provider ON. SMS provider: Twilio Verify."
  step "Twilio Account SID: $TWILIO_ACCOUNT_SID   Twilio Verify Service SID: $TWILIO_VERIFY_SERVICE_SID"
  step "Twilio Auth Token: copy TWILIO_AUTH_TOKEN from $ENV_FILE (never typed here)."
  step "Confirm phone: ON (users must enter the code). Save."
  pause "Press Enter when Phone shows Twilio Verify and is enabled"
done
note "Local development and CI use Supabase's fixed test numbers; Twilio is only wired to the hosted projects."

# ── 7. Stripe test mode ───────────────────────────────────────────────────
stage "Stripe: test mode (staging)"
open_url "https://dashboard.stripe.com/login"
step "Sign in to the Grassroots Headquarters Stripe account (register at dashboard.stripe.com/register as a business if there is none)."
step "Switch the Test mode toggle (top right) ON for this stage."
open_url "https://dashboard.stripe.com/test/products/create"
step "Name: Client Portal. Recurring, Monthly, GBP; the amount is the Add-on's price per Company per month (agree it with the business; new prices can be added later). Save product."
step "On the product page, copy the Price ID (price_…)."
ask STRIPE_TEST_PRICE_ID "Paste the test Price ID:"
write_env STRIPE_TEST_PRICE_ID "$STRIPE_TEST_PRICE_ID"
open_url "https://dashboard.stripe.com/test/coupons/create"
step "Name: Referral free month. Percentage discount: 100%. Duration: Once. Open the ID field and set it to exactly: referral-free-month. Create."
note "The code relies on that fixed coupon id in both test and live mode, so it is not stored as a secret."
pause "Press Enter when the coupon exists"
open_url "https://dashboard.stripe.com/test/webhooks/create"
step "Endpoint URL: $(supabase_url "$SUPABASE_STAGING_PROJECT_REF")/functions/v1/stripe-webhook"
step "Events: checkout.session.completed, customer.subscription.created, customer.subscription.updated, customer.subscription.deleted, invoice.paid, invoice.payment_failed. Add endpoint."
step "On the endpoint page, Signing secret → Reveal (whsec_…)."
ask_secret STRIPE_TEST_WEBHOOK_SECRET "Paste the test webhook signing secret:"
write_env STRIPE_TEST_WEBHOOK_SECRET "$STRIPE_TEST_WEBHOOK_SECRET"
open_url "https://dashboard.stripe.com/test/apikeys"
step "Secret key row → Reveal test key (sk_test_…)."
ask_secret STRIPE_TEST_SECRET_KEY "Paste the test secret key:"
write_env STRIPE_TEST_SECRET_KEY "$STRIPE_TEST_SECRET_KEY"
open_url "https://dashboard.stripe.com/test/settings/billing/portal"
step "Customer portal: Activate it, allow customers to update payment methods and view invoices. Save."
pause

# ── 8. Stripe live mode ───────────────────────────────────────────────────
stage "Stripe: live mode (production)"
say "Live keys only exist once Stripe has activated the account (business details, bank account); that can take days."
open_url "https://dashboard.stripe.com/account/onboarding"
if confirm "Is the Stripe account activated for live payments?"; then
  step "Switch Test mode OFF."
  open_url "https://dashboard.stripe.com/products/create"
  step "Create the same product: Client Portal, Recurring, Monthly, GBP, same amount. Copy the live Price ID."
  ask STRIPE_LIVE_PRICE_ID "Paste the live Price ID:"
  write_env STRIPE_LIVE_PRICE_ID "$STRIPE_LIVE_PRICE_ID"
  open_url "https://dashboard.stripe.com/coupons/create"
  step "Same coupon: Referral free month, 100% once, ID exactly referral-free-month. Create."
  pause "Press Enter when the live coupon exists"
  open_url "https://dashboard.stripe.com/webhooks/create"
  step "Endpoint URL: $(supabase_url "$SUPABASE_PRODUCTION_PROJECT_REF")/functions/v1/stripe-webhook, same six events."
  step "Signing secret → Reveal."
  ask_secret STRIPE_LIVE_WEBHOOK_SECRET "Paste the live webhook signing secret:"
  write_env STRIPE_LIVE_WEBHOOK_SECRET "$STRIPE_LIVE_WEBHOOK_SECRET"
  open_url "https://dashboard.stripe.com/apikeys"
  step "Secret key → Reveal live key (sk_live_…)."
  ask_secret STRIPE_LIVE_SECRET_KEY "Paste the live secret key:"
  write_env STRIPE_LIVE_SECRET_KEY "$STRIPE_LIVE_SECRET_KEY"
  open_url "https://dashboard.stripe.com/settings/billing/portal"
  step "Activate the live Customer portal with the same settings."
  pause
else
  warn "skipping live mode; re-run this wizard after activation (saved values are kept)."
  SKIPPED+=("Stripe live mode: product, coupon, webhook and keys, then re-run the wizard")
fi

# ── 9. Sentry ─────────────────────────────────────────────────────────────
stage "Sentry: organisation, projects and auth token"
open_url "https://sentry.io/organizations/new/"
step "Sign in (sign up with a Grassroots Headquarters login if needed). Create organisation 'Grassroots Headquarters' if it is missing."
note "If asked for a data storage location, choose the EU."
step "Copy the organisation's address from the browser: https://<slug>.sentry.io or https://<slug>.de.sentry.io for EU."
ask SENTRY_URL "Paste the organisation URL:"
SENTRY_URL="${SENTRY_URL%/}"
SENTRY_ORG="${SENTRY_URL#https://}"; SENTRY_ORG="${SENTRY_ORG%%.*}"
write_env SENTRY_URL "$SENTRY_URL"
write_env SENTRY_ORG "$SENTRY_ORG"
say "Organisation slug: $SENTRY_ORG"
for project in "$SENTRY_PROJECT_ADMIN:Next.js:SENTRY_DSN_ADMIN" "$SENTRY_PROJECT_MOBILE:React Native:SENTRY_DSN_MOBILE" "$SENTRY_PROJECT_EDGE:Deno:SENTRY_DSN_EDGE"; do
  name="${project%%:*}"; rest="${project#*:}"; platform="${rest%%:*}"; dsn_key="${rest#*:}"
  open_url "$SENTRY_URL/projects/new/"
  step "Platform: $platform. Project name: $name. Create project (skip the install instructions)."
  open_url "$SENTRY_URL/settings/projects/$name/keys/"
  step "Copy the DSN (https://…@…ingest…sentry.io/…)."
  ask "$dsn_key" "Paste the $name DSN:"
  write_env "$dsn_key" "${!dsn_key}"
done
write_env SENTRY_PROJECT_ADMIN "$SENTRY_PROJECT_ADMIN"
write_env SENTRY_PROJECT_MOBILE "$SENTRY_PROJECT_MOBILE"
write_env SENTRY_PROJECT_EDGE "$SENTRY_PROJECT_EDGE"
open_url "$SENTRY_URL/settings/auth-tokens/"
step "Create New Token → name 'my-builder-app ci' (organisation token; it can upload source maps and create releases). Copy it."
ask_secret SENTRY_AUTH_TOKEN "Paste the Sentry auth token:"
write_env SENTRY_AUTH_TOKEN "$SENTRY_AUTH_TOKEN"

# ── 10. Expo / EAS ────────────────────────────────────────────────────────
stage "Expo / EAS: organisation, token and project"
open_url "https://expo.dev/signup"
step "Sign in or sign up, then go to Accounts → Create organization: name it grassroots-headquarters and invite the team."
ask EXPO_ORG "Expo organisation name (from https://expo.dev/accounts/<name>):"
write_env EXPO_ORG "$EXPO_ORG"
open_url "https://expo.dev/accounts/$EXPO_ORG/settings/access-tokens"
step "Create token → name 'github-actions' → copy it."
ask_secret EXPO_TOKEN "Paste the Expo access token:"
write_env EXPO_TOKEN "$EXPO_TOKEN"
if [[ -d "$REPO_ROOT/apps/mobile" ]]; then
  say "apps/mobile exists; eas init creates the EAS project and writes its id into the app config."
  if confirm "Run eas init in apps/mobile now (owner: $EXPO_ORG)?"; then
    (cd "$REPO_ROOT/apps/mobile" && EXPO_TOKEN="$EXPO_TOKEN" npx -y eas-cli@latest init) \
      || warn "eas init did not finish; run it by hand in apps/mobile"
    EAS_PROJECT_ID=""
    if command -v jq >/dev/null 2>&1 && [[ -f "$REPO_ROOT/apps/mobile/app.json" ]]; then
      EAS_PROJECT_ID=$(jq -r '.expo.extra.eas.projectId // empty' "$REPO_ROOT/apps/mobile/app.json" 2>/dev/null || true)
    fi
    [[ -n "$EAS_PROJECT_ID" ]] || ask EAS_PROJECT_ID "Paste the EAS project id eas init printed:"
    write_env EAS_PROJECT_ID "$EAS_PROJECT_ID"
    note "Commit the app config change (extra.eas.projectId) on a branch; it is not a secret."
  else
    SKIPPED+=("eas init in apps/mobile (sets extra.eas.projectId)")
  fi
else
  warn "apps/mobile does not exist yet (ticket #24 creates it); run 'npx eas-cli init' there later."
  SKIPPED+=("eas init in apps/mobile once the Mobile app exists")
fi

# ── 11. Apple + Google ────────────────────────────────────────────────────
stage "Apple Developer Program and Google Play Console"
open_url "https://developer.apple.com/programs/enroll/"
step "Enrol as an Organization under Grassroots Headquarters (needs the company's D-U-N-S number and someone with legal authority; approval takes days)."
step "Use a shared Grassroots Headquarters Apple ID as Account Holder, not a personal one."
confirm "Is the Apple Developer Program enrolment done (or submitted)?" || SKIPPED+=("Apple Developer Program enrolment")
ask APPLE_TEAM_ID "Apple Team ID (Membership details; leave blank if not yet known):"
[[ -n "$APPLE_TEAM_ID" ]] && write_env APPLE_TEAM_ID "$APPLE_TEAM_ID"
open_url "https://play.google.com/console/signup"
step "Create an Organization developer account (one-off fee) owned by a Grassroots Headquarters Google Workspace account, not a personal Gmail."
confirm "Is the Google Play Console organisation account created?" || SKIPPED+=("Google Play Console organisation account")
warn "Do not create the App Store Connect or Play app records yet."
warn "App id $APP_ID is a placeholder and becomes permanent at the first store upload: confirm the final id, and the app.example.com domain, with the business before the first store build."
pause

# ── 12. Vercel: Admin app ─────────────────────────────────────────────────
stage "Vercel: my-builder-admin (Admin app)"
open_url "https://vercel.com/new"
step "Sign in; choose or create the Grassroots Headquarters team. Import Git Repository → install the Vercel GitHub app on the organisation with access to $GITHUB_REPO → Import."
step "Project name: my-builder-admin. Framework: Next.js. Root Directory: apps/admin (tick 'Include source files outside of the Root Directory')."
step "Leave build/install defaults (pnpm is detected from packageManager). Deploy; a failed first build is fine before the app exists on main."
step "After creating: Settings → Git → Production Branch: main. Previews are built for every pull request by default."
ask VERCEL_TEAM "Vercel team slug (from https://vercel.com/<team>):"
write_env VERCEL_TEAM "$VERCEL_TEAM"
ask ADMIN_APP_URL "Admin app URL (its Vercel domain, e.g. https://my-builder-admin.vercel.app, until app.example.com is confirmed):"
ADMIN_APP_URL="${ADMIN_APP_URL%/}"
write_env ADMIN_APP_URL "$ADMIN_APP_URL"
say "Environment variables for my-builder-admin:"
say "  Production : NEXT_PUBLIC_SUPABASE_URL / NEXT_PUBLIC_SUPABASE_ANON_KEY = production project, NEXT_PUBLIC_APP_URL = $ADMIN_APP_URL"
say "  Preview+Dev: NEXT_PUBLIC_SUPABASE_URL / NEXT_PUBLIC_SUPABASE_ANON_KEY = staging project"
say "  All        : NEXT_PUBLIC_SENTRY_DSN, SENTRY_ORG, SENTRY_PROJECT=$SENTRY_PROJECT_ADMIN, SENTRY_URL, SENTRY_AUTH_TOKEN (sensitive)"
if confirm "Write them with the Vercel CLI now (it links apps/admin to the project)?" && vercel_link "$REPO_ROOT/apps/admin" my-builder-admin; then
  vercel_env "$REPO_ROOT/apps/admin" NEXT_PUBLIC_SUPABASE_URL "$SUPABASE_PRODUCTION_URL" production
  vercel_env "$REPO_ROOT/apps/admin" NEXT_PUBLIC_SUPABASE_ANON_KEY "$SUPABASE_PRODUCTION_ANON_KEY" production
  vercel_env "$REPO_ROOT/apps/admin" NEXT_PUBLIC_APP_URL "$ADMIN_APP_URL" production
  for environment in preview development; do
    vercel_env "$REPO_ROOT/apps/admin" NEXT_PUBLIC_SUPABASE_URL "$SUPABASE_STAGING_URL" "$environment"
    vercel_env "$REPO_ROOT/apps/admin" NEXT_PUBLIC_SUPABASE_ANON_KEY "$SUPABASE_STAGING_ANON_KEY" "$environment"
  done
  for environment in production preview development; do
    vercel_env "$REPO_ROOT/apps/admin" NEXT_PUBLIC_SENTRY_DSN "$SENTRY_DSN_ADMIN" "$environment"
    vercel_env "$REPO_ROOT/apps/admin" SENTRY_ORG "$SENTRY_ORG" "$environment"
    vercel_env "$REPO_ROOT/apps/admin" SENTRY_PROJECT "$SENTRY_PROJECT_ADMIN" "$environment"
    vercel_env "$REPO_ROOT/apps/admin" SENTRY_URL "$SENTRY_URL" "$environment"
    vercel_env "$REPO_ROOT/apps/admin" SENTRY_AUTH_TOKEN "$SENTRY_AUTH_TOKEN" "$environment"
  done
else
  warn "set them by hand: values are in $ENV_FILE (SENTRY_AUTH_TOKEN as a Sensitive variable)."
  SKIPPED+=("Vercel my-builder-admin environment variables: https://vercel.com/$VERCEL_TEAM/my-builder-admin/settings/environment-variables")
fi
for ref in "$SUPABASE_STAGING_PROJECT_REF" "$SUPABASE_PRODUCTION_PROJECT_REF"; do
  open_url "https://supabase.com/dashboard/project/$ref/auth/url-configuration"
  redirects="$ADMIN_APP_URL/**, mybuilderapp://**"
  [[ "$ref" == "$SUPABASE_STAGING_PROJECT_REF" ]] && redirects+=", https://*-$VERCEL_TEAM.vercel.app/** (PR previews)"
  step "Site URL: $ADMIN_APP_URL. Redirect URLs: $redirects. Save."
  pause
done

# ── 13. Vercel: Mobile web test site ──────────────────────────────────────
stage "Vercel: my-builder-mobile-web-test (Mobile app web build, internal only)"
open_url "https://vercel.com/new"
step "Import $GITHUB_REPO again. Project name: my-builder-mobile-web-test. Framework Preset: Other. Root Directory: apps/mobile (include files outside the root)."
step "Build Command: pnpm exec expo export -p web   Output Directory: dist   Install Command: default. Deploy."
step "Settings → Git → Production Branch: main."
say "Environment variables (all environments): EXPO_PUBLIC_SUPABASE_URL / EXPO_PUBLIC_SUPABASE_ANON_KEY = staging project, EXPO_PUBLIC_SENTRY_DSN."
if confirm "Write them with the Vercel CLI now (it links apps/mobile to the project)?" && vercel_link "$REPO_ROOT/apps/mobile" my-builder-mobile-web-test; then
  for environment in production preview development; do
    vercel_env "$REPO_ROOT/apps/mobile" EXPO_PUBLIC_SUPABASE_URL "$SUPABASE_STAGING_URL" "$environment"
    vercel_env "$REPO_ROOT/apps/mobile" EXPO_PUBLIC_SUPABASE_ANON_KEY "$SUPABASE_STAGING_ANON_KEY" "$environment"
    vercel_env "$REPO_ROOT/apps/mobile" EXPO_PUBLIC_SENTRY_DSN "$SENTRY_DSN_MOBILE" "$environment"
  done
else
  warn "set them by hand from $ENV_FILE."
  SKIPPED+=("Vercel my-builder-mobile-web-test environment variables: https://vercel.com/$VERCEL_TEAM/my-builder-mobile-web-test/settings/environment-variables")
fi
open_url "https://vercel.com/$VERCEL_TEAM/my-builder-mobile-web-test/settings/deployment-protection"
step "Vercel Authentication: ON for all deployments (production included), so only team members can open the site. Save."
confirm "Is deployment protection on for every deployment?" || SKIPPED+=("Vercel deployment protection on my-builder-mobile-web-test")
ask MOBILE_WEB_TEST_URL "Mobile web test site URL (e.g. https://my-builder-mobile-web-test.vercel.app):"
write_env MOBILE_WEB_TEST_URL "${MOBILE_WEB_TEST_URL%/}"

# ── 14. Publish ───────────────────────────────────────────────────────────
stage "Publish: GitHub Actions secrets and variables, Edge Function secrets"
say "No browser needed. Everything below is read from the values saved in $ENV_FILE."
set_secret SUPABASE_ACCESS_TOKEN "$SUPABASE_ACCESS_TOKEN"
set_secret SUPABASE_STAGING_PROJECT_REF "$SUPABASE_STAGING_PROJECT_REF"
set_secret SUPABASE_STAGING_DB_PASSWORD "$SUPABASE_STAGING_DB_PASSWORD"
set_secret SUPABASE_PRODUCTION_PROJECT_REF "$SUPABASE_PRODUCTION_PROJECT_REF"
set_secret SUPABASE_PRODUCTION_DB_PASSWORD "$SUPABASE_PRODUCTION_DB_PASSWORD"
set_secret EXPO_TOKEN "$EXPO_TOKEN"
set_secret SENTRY_AUTH_TOKEN "$SENTRY_AUTH_TOKEN"
set_var SENTRY_ORG "$SENTRY_ORG"
set_var SENTRY_PROJECT_ADMIN "$SENTRY_PROJECT_ADMIN"
set_var SENTRY_PROJECT_MOBILE "$SENTRY_PROJECT_MOBILE"
set_var SENTRY_PROJECT_EDGE "$SENTRY_PROJECT_EDGE"
set_var SENTRY_URL "$SENTRY_URL"
ask INVITE_LINK_BASE_URL "Invite link base URL (Enter for $ADMIN_APP_URL; becomes https://app.example.com's real domain later):"
INVITE_LINK_BASE_URL="${INVITE_LINK_BASE_URL:-$ADMIN_APP_URL}"
write_env INVITE_LINK_BASE_URL "${INVITE_LINK_BASE_URL%/}"
say "Edge Function secrets on staging ($SUPABASE_STAGING_PROJECT_REF): Stripe test mode"
edge_secrets "$SUPABASE_STAGING_PROJECT_REF" \
  "STRIPE_SECRET_KEY=$STRIPE_TEST_SECRET_KEY" \
  "STRIPE_WEBHOOK_SECRET=$STRIPE_TEST_WEBHOOK_SECRET" \
  "STRIPE_CLIENT_PORTAL_PRICE_ID=$STRIPE_TEST_PRICE_ID" \
  "TWILIO_ACCOUNT_SID=$TWILIO_ACCOUNT_SID" \
  "TWILIO_AUTH_TOKEN=$TWILIO_AUTH_TOKEN" \
  "TWILIO_MESSAGING_SERVICE_SID=$TWILIO_MESSAGING_SERVICE_SID" \
  "INVITE_LINK_BASE_URL=$INVITE_LINK_BASE_URL" \
  "SENTRY_DSN=$SENTRY_DSN_EDGE"
say "Edge Function secrets on production ($SUPABASE_PRODUCTION_PROJECT_REF): Stripe live mode"
if [[ -n "${STRIPE_LIVE_SECRET_KEY:-}" ]]; then
  edge_secrets "$SUPABASE_PRODUCTION_PROJECT_REF" \
    "STRIPE_SECRET_KEY=$STRIPE_LIVE_SECRET_KEY" \
    "STRIPE_WEBHOOK_SECRET=$STRIPE_LIVE_WEBHOOK_SECRET" \
    "STRIPE_CLIENT_PORTAL_PRICE_ID=$STRIPE_LIVE_PRICE_ID" \
    "TWILIO_ACCOUNT_SID=$TWILIO_ACCOUNT_SID" \
    "TWILIO_AUTH_TOKEN=$TWILIO_AUTH_TOKEN" \
    "TWILIO_MESSAGING_SERVICE_SID=$TWILIO_MESSAGING_SERVICE_SID" \
    "INVITE_LINK_BASE_URL=$INVITE_LINK_BASE_URL" \
    "SENTRY_DSN=$SENTRY_DSN_EDGE"
else
  warn "no Stripe live keys yet: setting production Edge Function secrets without Stripe."
  SKIPPED+=("Production Edge Function secrets STRIPE_* once Stripe live mode is done (re-run the wizard)")
  edge_secrets "$SUPABASE_PRODUCTION_PROJECT_REF" \
    "TWILIO_ACCOUNT_SID=$TWILIO_ACCOUNT_SID" \
    "TWILIO_AUTH_TOKEN=$TWILIO_AUTH_TOKEN" \
    "TWILIO_MESSAGING_SERVICE_SID=$TWILIO_MESSAGING_SERVICE_SID" \
    "INVITE_LINK_BASE_URL=$INVITE_LINK_BASE_URL" \
    "SENTRY_DSN=$SENTRY_DSN_EDGE"
fi
note "SENTRY_RELEASE is set per deploy by the release workflow, not here."
note "Keep $ENV_FILE private (mode 600, git-ignored)."
note "Next: the first-run checklist in docs/delivery.md (EAS environment variables, submit profile ids, GitHub environments)."

finish
}

run_wizard "$@"; exit
